import{_ as e,c as l,o as s,b0 as i}from"./chunks/framework.BWMBvyU7.js";const n="data:image/png;base64,",d="/programming-docs/assets/image-20220217161533214.ArG4TrgA.png",g=JSON.parse('{"title":"LV105-文件系统简介","description":null,"frontmatter":{"title":"LV105-文件系统简介","date":"2026-03-11T15:53:14.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/os/linux-basic/126d38a64272218544b03607","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-11T15:53:14.536Z","fulluuid":"544b03607e604295987134d7bd7106ac","useduuid":"544b03607"}},"headers":[],"relativePath":"sdoc/os/linux-basic/126d38a64272218544b03607.md","filePath":"sdoc/03-操作系统/01-Linux基础/LV105-文件系统简介.md","lastUpdated":1773672539000}'),f={name:"sdoc/os/linux-basic/126d38a64272218544b03607.md"};function p(o,t,a,x,r,z){return s(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="lv105-文件系统简介" tabindex="-1">LV105-文件系统简介 <a class="header-anchor" href="#lv105-文件系统简介" aria-label="Permalink to &quot;LV105-文件系统简介&quot;">​</a></h1><p>本文主要是 Linux——文件系统相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正 😃。</p><p>文件系统用于组织和管理计算机存储设备上的大量文件，并提供用户交互接口。</p><h2 id="一、文件系统类型" tabindex="-1">一、文件系统类型 <a class="header-anchor" href="#一、文件系统类型" aria-label="Permalink to &quot;一、文件系统类型&quot;">​</a></h2><p>linux 是一种兼容性很高的系统，支持很多的文件系统格式，大体可有以下几类：</p><table><tbody><tr><td align="center" width="150px"> 磁盘文件系统 </td><td align="left"> 指本地主机中实际可以访问到的文件系统，包括硬盘、CD-ROM、DVD、USB 存储器、磁盘阵列等。常见文件系统格式有：autofs、coda、Ext（Extended File sytem，扩展文件系统）、Ext3、Ext4、VFAT、ISO9660（通常是 CD-ROM）、UFS（Unix File System，Unix 文件系统）、FAT、FAT16、FAT32、NTFS 等 </td></tr><tr><td align="center" width="150px"> 网络文件系统 </td><td align="left"> 是可以远程访问的文件系统，这种文件系统在服务器端仍是本地的磁盘文件系统，客户机通过网络远程访问数据。常见文件系统格式有：NFS、Samba 等 </td></tr><tr><td align="center" width="150px"> 专有/虚拟文件系统 </td><td align="left"> 不驻留在磁盘上的文件系统。常见格式有：TMPFS（临时文件系统）、PROCFS（Process File System，进程文件系统）和 LOOPBACKFS（Loopback File System，回送文件系统）</td></tr></tbody></table><p>目前 Ext4 是 Linux 系统广泛使用的一种文件格式。在 Ext3 基础上，对有效性保护、数据完整性、数据访问速度、向下兼容性等方面做了改进。最大特点是日志文件系统：可将整个磁盘的写入动作完整地记录在磁盘的某个区域上，以便在必要时回溯追踪。</p><h2 id="二、分区与目录" tabindex="-1">二、分区与目录 <a class="header-anchor" href="#二、分区与目录" aria-label="Permalink to &quot;二、分区与目录&quot;">​</a></h2><img src="'+n+'" alt="image-20220217160908947" style="zoom:50%;"><p>在微软 Windows 操作系统，我们会将硬盘上进行分区，并用 A： 、 B： 、 C： 、 D： 等符号标识(也就是盘符)。在存取文件时一定要清楚存放在哪个磁盘的哪个目录下。</p><img src="'+d+'" alt="image-20220217161533214" style="zoom:50%;"><p>Linux 的文件组织模式犹如一颗 <strong>倒置的树</strong>，所有存储设备作为这颗树的一个子目录。存取文件时只需确定目录就可以了，无需考虑物理存储位置。在 linux 中可以说一切皆文件，并没有盘符这样的概念。</p><p>在 Windows 下，目录结构属于分区；在 Linux 下，分区属于目录结构。在 Linux 中，将所有硬件都视为文件来处理，包括硬盘分区、 CD-ROM 、软驱以及其他 USB 移动设备等。为了能够按照统一的方式和方法访问文件资源， Linux 中提供了对每种硬件设备相应的设备文件。一旦 Linux 系统可以访问到硬件，就将其上的文件系统挂载到目录树中的一个子目录中。例如，当我们插入一个 U 盘时， Linux 自动识别后，将其挂载到 /media/disk 目录下。而不像 Windows 系统将 U 盘作为新驱动器，表示为 F： 盘或者其他盘符。</p><h2 id="三、基本目录" tabindex="-1">三、基本目录 <a class="header-anchor" href="#三、基本目录" aria-label="Permalink to &quot;三、基本目录&quot;">​</a></h2><p>Linux 是完全开源的软件，各 Linux 发行机构都可以按照自己的需求对文件系统进行裁剪，所以如此众多的 Linux 发行版本的目录结构也不尽相同。为了规范文件目录命名和存放标准，相关组织颁发了文件层次结构标准（ FHS，File Hierarchy Standard ）， 2004 年发行版本 FHS 2.3 。 Ubuntu Linux 系统同样也遵循这个标准。</p><table style="font-size:12.5px;"><tbody><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="center" width="100px" colspan="2"> 目录名 </td><td style="font-size:12.5px;" align="center" colspan="2"> 描述 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="30px" rowspan="47">/</td><td style="font-size:12.5px;" align="left" colspan="3"> Linux 文件系统根目录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/bin </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放系统中最常用的可执行文件（二进制）</td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/boot </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放 Linux 内核和系统启动文件，包括 Grub、lilo 启动器程序 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/cdrom </td><td style="font-size:12.5px;" align="left" colspan="2"> 光盘目录，如果插入光盘会出现光盘内容 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/dev </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放所有设备文件，包括硬盘、分区、键盘、鼠标、USB、tty 等 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/etc </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放系统的所有配置文件，例如 passwd 存放用户账户信息，hostname 存放主机名等 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/home </td><td style="font-size:12.5px;" align="left" colspan="2"> 用户主目录的默认位置 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/initrd </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放启动时挂载 initrd.img 映像文件的目录，以及载入所需设备模块的目录。 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/lib </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放共享的库文件，包含许多被/bin 和/sbin 中程序使用的库文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/lost+found </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放由 fsck 放置的零散文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/media </td><td style="font-size:12.5px;" align="left" colspan="2"> Ubuntu 系统自动挂载 CD-ROM、软驱、USB 存储器后，存放临时读入的文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/mnt </td><td style="font-size:12.5px;" align="left" colspan="2"> 该目录通常用于作为被挂载的文件系统的挂载点 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/opt </td><td style="font-size:12.5px;" align="left" colspan="2"> 作为可选文件和程序的存放目录，主要被第三方开发者用来简易地安装和卸装他们的软件包 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/proc </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放所有标志为文件的进程，它们是通过进程号或其他的系统动态信息进行标识，例如 cpuinfo 文件存放 CPU 当前工作状态的数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/root </td><td style="font-size:12.5px;" align="left" colspan="2"> 根用户（超级用户）的主目录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/run </td><td style="font-size:12.5px;" align="left" colspan="2"> 是一个临时文件系统，存储系统启动以来的信息。当系统重启时，这个目录下的文件应该被删掉或清除。如果系统上有 /var/run 目录，应该让它指向 run。</td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/sbin </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放更多的可执行文件（二进制），包括系统管理、目录查询等关键命令文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/snap </td><td style="font-size:12.5px;" align="left" colspan="2"> snap 应用框架的程序文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/srv </td><td style="font-size:12.5px;" align="left" colspan="2"> 服务目录，存放本地服务的相关文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/sys </td><td style="font-size:12.5px;" align="left" colspan="2"> 系统目录，存放系统硬件信息的相关文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/tmp </td><td style="font-size:12.5px;" align="left" colspan="2"> 存放用户和程序的临时文件，所有用户对该目录都有读写权限 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px" rowspan="14">/usr </td><td style="font-size:12.5px;" align="left" colspan="2"> 用于存放与系统用户直接有关的文件和目录，例如应用程序及支持它们的库文件。 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px">/usr/X11R6</td><td style="font-size:12.5px;" align="left"> X Window 系统。 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/bin </td><td style="font-size:12.5px;" align="left"> 用户和管理员的标准命令 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/include </td><td style="font-size:12.5px;" align="left"> c/C++等各种开发语言环境的标准 include 文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/lib </td><td style="font-size:12.5px;" align="left"> 应用程序及程序包的连接库 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/local </td><td style="font-size:12.5px;" align="left"> 系统管理员安装的应用程序目录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/local/share </td><td style="font-size:12.5px;" align="left"> 系统管理员安装的共享文件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/sbin </td><td style="font-size:12.5px;" align="left"> 用户和管理员的标准命令 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/share </td><td style="font-size:12.5px;" align="left"> 存放使用手册等共享文件的目录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/share/dict </td><td style="font-size:12.5px;" align="left"> 存放词表的目录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/share/man </td><td style="font-size:12.5px;" align="left"> 系统使用手册 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/share/misc </td><td style="font-size:12.5px;" align="left"> 一般数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/share/sgml </td><td style="font-size:12.5px;" align="left"> SGML 数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /usr/share/xml </td><td style="font-size:12.5px;" align="left"> XML 数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px" rowspan="12">/var </td><td style="font-size:12.5px;" align="left" colspan="2"> 通常用于存放长度可变的文件，例如日志文件和打印机文件。</td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/cache </td><td style="font-size:12.5px;" align="left"> 应用程序缓存目录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/crash </td><td style="font-size:12.5px;" align="left"> 系统错误信息 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/games </td><td style="font-size:12.5px;" align="left"> 游戏数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/lib </td><td style="font-size:12.5px;" align="left"> 各种状态数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/lock </td><td style="font-size:12.5px;" align="left"> 文件锁定纪录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/log </td><td style="font-size:12.5px;" align="left"> 日志记录 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/mail </td><td style="font-size:12.5px;" align="left"> 电子邮件 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/opt </td><td style="font-size:12.5px;" align="left"> /opt 目录的变量数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/run </td><td style="font-size:12.5px;" align="left"> 进程的标示数据 </td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/spool </td><td style="font-size:12.5px;" align="left"> 存放电子邮件，打印任务等的队列目录。</td></tr><tr style="font-size:12.5px;"><td style="font-size:12.5px;" align="left" width="100px"> /var/tmp </td><td style="font-size:12.5px;" align="left"> 临时文件目录 </td></tr></tbody></table>',16)])])}const h=e(f,[["render",p]]);export{g as __pageData,h as default};
